import{_ as e,c as t,o as r,b2 as s}from"./chunks/framework.CUhoHPxN.js";const h=JSON.parse('{"title":"C7JsonTable（C7 JSON 表格 / 一体化列表）设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-08-c7-json-table-design.md","filePath":"superpowers/specs/2026-05-08-c7-json-table-design.md"}'),n={name:"superpowers/specs/2026-05-08-c7-json-table-design.md"};function g(c,o,d,l,a,i){return r(),t("div",null,[...o[0]||(o[0]=[s('<h1 id="c7jsontable-c7-json-表格-一体化列表-设计说明" tabindex="-1">C7JsonTable（C7 JSON 表格 / 一体化列表）设计说明 <a class="header-anchor vp-link" href="#c7jsontable-c7-json-表格-一体化列表-设计说明" aria-label="Permalink to &quot;C7JsonTable（C7 JSON 表格 / 一体化列表）设计说明&quot;">​</a></h1><p><strong>日期</strong>：2026-05-08<br><strong>状态</strong>：已定稿（经 brainstorming 澄清 <strong>1C、2B、3B、4A、5A、6C</strong> 与「设计确认」）<br><strong>依据</strong>：<code>原始需求/前端/C7JSON表格.md</code>、<code>docs/superpowers/specs/2026-05-08-c7-json-table-column-design.md</code>（列契约与 <strong><code>C7JsonTableColumn</code></strong> 引用）<br><strong>实现路径</strong>：首版 <strong>单文件 <code>quick-ui/src/packages/C7JsonTable/index.vue</code></strong>；若体量过大再抽 <strong><code>useJsonTableQuery.ts</code></strong> / <strong><code>useTableColumnSettings.ts</code></strong> 等，<strong>不</strong>首版拆多子组件。</p><hr><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><ul><li><strong>背景</strong>：后台列表页重复包含搜索区、表格区、工具栏、分页、排序、删除、导出、列显隐等；希望 <strong>配置驱动</strong> 快速搭建，并保留 <strong>slot</strong> 扩展点。</li><li><strong>目标</strong>：提供 <strong><code>C7JsonTable</code></strong>：传入 <strong><code>listFunction</code></strong> 与列/搜索配置即可运行；内置参数组装、分页、排序、列设置（localStorage）、批量删除与导出、刷新；与 <strong><code>C7JsonTableColumn</code></strong>、<strong><code>C7Pagination</code></strong>、<strong><code>C7ExcelDownload</code></strong> 契约对齐。</li><li><strong>非目标（首版）</strong>：<strong><code>searchColumns</code> 全量对齐 <code>C7JsonForm</code></strong>（联动、<code>visibleWhen</code>、<code>rules</code>、全部 <code>type</code>）；树表懒加载的完整业务验收；列设置 <strong>后端持久化</strong>（仅 <strong>localStorage</strong>）。</li></ul><hr><h2 id="_2-命名、边界与落点" tabindex="-1">2. 命名、边界与落点 <a class="header-anchor vp-link" href="#_2-命名、边界与落点" aria-label="Permalink to &quot;2. 命名、边界与落点&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>约定</th></tr></thead><tbody><tr><td><strong>对外组件名</strong></td><td><strong><code>C7JsonTable</code></strong></td></tr><tr><td><strong>目录</strong></td><td><strong><code>quick-ui/src/packages/C7JsonTable/index.vue</code></strong>（首版）</td></tr><tr><td><strong>全局注册</strong></td><td><strong><code>quick-ui/src/packages/index.js</code></strong>：<strong><code>export</code></strong> + <strong><code>installPackages</code></strong>（与现有 C7 包一致）</td></tr></tbody></table></div><p><strong>职责</strong>：搜索区渲染（约定子集）、工具栏、<strong><code>el-table</code></strong> 数据绑定、<strong>内置多选/序号列</strong>、默认 <strong><code>C7JsonTableColumn</code></strong> 列区、<strong><code>C7Pagination</code></strong>、请求与分页/排序参数组装、列显隐与 localStorage、删除/导出流程、事件与 <strong>expose</strong>。</p><p><strong>不负责</strong>：列单元格 <strong><code>columnType</code></strong> 细节（由 <strong><code>C7JsonTableColumn</code></strong> 承担，见列设计说明）。</p><hr><h2 id="_3-与-c7jsontablecolumn-的关系-澄清-1c" tabindex="-1">3. 与 C7JsonTableColumn 的关系（澄清 1C） <a class="header-anchor vp-link" href="#_3-与-c7jsontablecolumn-的关系-澄清-1c" aria-label="Permalink to &quot;3. 与 C7JsonTableColumn 的关系（澄清 1C）&quot;">​</a></h2><ul><li><strong>默认</strong>：在 <strong><code>el-table</code></strong> 内，于 <strong><code>type=&quot;selection&quot;</code></strong>、<strong><code>type=&quot;index&quot;</code></strong>（若开启）之后，渲染 <strong><code>&lt;C7JsonTableColumn :columns=&quot;effectiveTableColumns&quot; /&gt;</code></strong>，其中 <strong><code>effectiveTableColumns</code></strong> 为合并列设置 <strong><code>_visible</code></strong> 与 <strong><code>order</code></strong> 后的列数组（与列组件 <strong><code>visible !== false</code></strong> 规则一致，见列 spec）。</li><li><strong>扩展</strong>：若提供 <strong><code>#table-columns</code></strong> 插槽，则 <strong>不渲染</strong> 默认 <strong><code>C7JsonTableColumn</code></strong>；由插槽 <strong>自行输出多个 <code>el-table-column</code> 或其它列组件</strong>。插槽 <strong>仅替换 <code>el-table</code> 下列子树</strong>，外层 <strong>仍为本组件持有的单个 <code>el-table</code></strong>。</li><li><strong>插槽作用域（建议注入，实现阶段以代码为准）</strong>：至少包含 <strong><code>tableColumns</code></strong>（当前生效列配置）、<strong><code>searchParam</code></strong>、<strong><code>selectedRows</code></strong>、<strong><code>refreshData</code></strong>、<strong><code>getDataList</code></strong>；便于自定义列区仍可调列表行为。</li></ul><p><strong>多选 / 序号</strong>：由 <strong><code>C7JsonTable</code></strong> 声明 <strong><code>el-table-column type=&quot;selection&quot;</code></strong>、<strong><code>type=&quot;index&quot;</code></strong>（与 <strong><code>C7JsonTableColumn</code> 设计</strong> 中「由父级声明」一致；此处父级即 <strong><code>C7JsonTable</code></strong>）。</p><hr><h2 id="_4-与-c7jsonform-的对齐-澄清-2b" tabindex="-1">4. 与 C7JsonForm 的对齐（澄清 2B） <a class="header-anchor vp-link" href="#_4-与-c7jsonform-的对齐-澄清-2b" aria-label="Permalink to &quot;4. 与 C7JsonForm 的对齐（澄清 2B）&quot;">​</a></h2><ul><li><strong><code>searchColumns[]</code></strong> 使用 <strong>C7JSON表单</strong>（<code>原始需求/前端/C7JSON表单.md</code>）中概念的 <strong>子集</strong>，字段名尽量一致：<strong><code>prop</code></strong>、<strong><code>label</code></strong>、<strong><code>type</code></strong>、<strong><code>order</code></strong>、<strong><code>span</code></strong>、<strong><code>defaultValue</code></strong> 等。</li><li><strong>首版支持的 <code>type</code></strong>（与原始表格需求一致）：<strong><code>input</code></strong>、<strong><code>select</code></strong>、<strong><code>date</code></strong>、<strong><code>daterange</code></strong>、<strong><code>slot</code></strong>。其它 JsonForm 类型（<code>upload</code>、<code>tree-select</code> 等）<strong>首版不支持</strong>；文档与实现中 <strong>开发环境</strong> 可对未知类型 <strong><code>console.warn</code></strong> 并跳过渲染。</li><li><strong>首版不实现</strong>：<strong><code>visibleWhen</code></strong>、<strong><code>disabledWhen</code></strong>、<strong><code>optionsWhen</code></strong>、<strong><code>linkage</code></strong>、<strong><code>rules</code></strong> 与表单项级校验；若后续需要，单独开变更将 JsonTable 搜索区 <strong>升级为嵌入 <code>C7JsonForm</code></strong> 或扩展 schema。</li></ul><hr><h2 id="_5-搜索数据模型" tabindex="-1">5. 搜索数据模型 <a class="header-anchor vp-link" href="#_5-搜索数据模型" aria-label="Permalink to &quot;5. 搜索数据模型&quot;">​</a></h2><ul><li><strong><code>defaultSearchParam</code></strong>：<strong>对象</strong>；组件 <strong>挂载时深拷贝</strong> 为内部 <strong><code>searchParam</code></strong> 初始值；<strong>重置</strong> 恢复为该快照。</li><li><strong>对外同步</strong>：通过 <strong><code>update:searchParam</code></strong>（及/或 <strong><code>v-model:searchParam</code></strong>，实现时与项目其它组件命名一致即可）把当前搜索对象同步给父级，保证 <strong>导出</strong> 与父级使用的快照一致。</li><li><strong>交互</strong>：<strong>Enter</strong> 触发查询（聚焦在搜索区内任一输入时）；<strong>重置</strong> 回到 <strong><code>defaultSearchParam</code></strong> 并重新拉数（页码是否回第一页见下节「分页行为」约定）。</li></ul><hr><h2 id="_6-数据获取与解析" tabindex="-1">6. 数据获取与解析 <a class="header-anchor vp-link" href="#_6-数据获取与解析" aria-label="Permalink to &quot;6. 数据获取与解析&quot;">​</a></h2><ul><li><strong><code>listFunction(params)</code></strong>：<strong><code>params</code></strong> 由组件组装：<br><strong><code>{ ...searchParam, pageNum, pageSize, orderByColumn, isAsc }</code></strong><br> 其中 <strong><code>pageNum</code> / <code>pageSize</code></strong> 与后端/若依风格不一致时，实现阶段在 <strong>implementation plan</strong> 中对照 <strong><code>quick-ui</code></strong> 现有列表页做一次字段名对齐（必要时提供 <strong>prop 映射</strong> 配置，<strong>首版 YAGNI</strong>：若全项目已统一为同一套字段名，则 <strong>不增加</strong> 映射 prop）。</li><li><strong><code>rowsKey</code> / <code>totalKey</code></strong>：从响应对象取列表与总数的 <strong>点路径</strong>（如 <strong><code>data.records</code></strong>、<strong><code>data.total</code></strong>）；解析失败时视为 <strong>空列表 / 0</strong> 并 <strong>开发环境 <code>console.warn</code></strong>。</li><li><strong><code>before-fetch(params)</code></strong>：若返回 <strong><code>false</code></strong>，<strong>取消</strong>本次请求（与常见若依封装约定一致时采用；若项目无此惯例则首版 <strong>仅 emit</strong>，不拦截——实现前在代码库中 <strong>核对</strong> <code>request</code> 封装，<strong>二选一写死</strong>在实现说明中）。</li><li><strong><code>after-fetch(rows, total)</code></strong>：列表成功写入后触发。</li><li><strong>错误（澄清 6C）</strong>：列表请求失败依赖 <strong>axios / request 拦截器</strong> 的 <strong>全局错误提示</strong>；组件 <strong><code>emit(&#39;fetch-error&#39;, err)</code></strong>（事件名实现时可选用 <strong><code>list-error</code></strong>，但 <strong>spec 与文档、实现三处统一</strong>）。组件 <strong>不默认二次 toast</strong>。</li></ul><hr><h2 id="_7-表格与排序" tabindex="-1">7. 表格与排序 <a class="header-anchor vp-link" href="#_7-表格与排序" aria-label="Permalink to &quot;7. 表格与排序&quot;">​</a></h2><ul><li><strong><code>el-table</code></strong>：<strong><code>border</code></strong>、<strong><code>stripe</code></strong>、<strong><code>row-key</code></strong>（来自 <strong><code>rowKey</code></strong> prop）、<strong><code>data</code></strong> 绑定列表行。</li><li><strong><code>sort-change</code></strong>：更新内部 <strong><code>orderByColumn</code> / <code>isAsc</code></strong>（或项目等价字段），并 <strong>重新请求</strong>；与 <strong><code>clear排序</code></strong> 行为与 Element Plus 表格一致即可。</li><li><strong>树形懒加载</strong>：<strong><code>lazy</code></strong>、<strong><code>load</code></strong>、<strong><code>tree-props</code></strong> 等 <strong>仅透传</strong> 至 <strong><code>el-table</code></strong>；首版 <strong>不将树表列入验收</strong>，仅保证不挡扩展。</li></ul><hr><h2 id="_8-分页-澄清-5a" tabindex="-1">8. 分页（澄清 5A） <a class="header-anchor vp-link" href="#_8-分页-澄清-5a" aria-label="Permalink to &quot;8. 分页（澄清 5A）&quot;">​</a></h2><ul><li>使用 <strong><code>C7Pagination</code></strong>：<strong><code>v-model:currentPage</code></strong>、<strong><code>v-model:pageSize</code></strong>，<strong><code>total</code></strong> 来自最近一次成功列表响应。</li><li><strong><code>change(page, pageSize)</code></strong>（或等价的 <strong><code>C7Pagination</code></strong> 汇总事件）：触发 <strong><code>listFunction</code></strong>。用户 <strong>切换 <code>pageSize</code></strong> 时依赖 <strong><code>C7Pagination</code></strong> 默认 <strong><code>autoReset</code></strong> 行为（回第一页）与拉数一致。</li><li><strong>搜索提交</strong>：建议 <strong>将 <code>currentPage</code> 置为 1</strong> 再请求（与常见 UX 一致）；<strong><code>refreshData</code></strong> 保留当前页（与原始需求一致）。</li></ul><hr><h2 id="_9-列设置与持久化-澄清-4a" tabindex="-1">9. 列设置与持久化（澄清 4A） <a class="header-anchor vp-link" href="#_9-列设置与持久化-澄清-4a" aria-label="Permalink to &quot;9. 列设置与持久化（澄清 4A）&quot;">​</a></h2><ul><li><strong>可参与列设置的列</strong>：<strong><code>tableColumns</code></strong> 中带 <strong><code>prop</code></strong> 的项。</li><li><strong>显示控制</strong>：运行时维护 <strong><code>_visible</code></strong>（或等价字段）；<strong><code>C7JsonTableColumn</code></strong> 侧使用其 <strong><code>visible</code></strong> 规则时，需与 JsonTable 合并策略一致：<strong>推荐</strong> 使用 <strong>内部 <code>normalizedColumns</code></strong>，从 <strong><code>tableColumns</code> + localStorage 覆盖</strong> 计算，<strong>避免直接 mutate</strong> 父级传入的只读 props。</li><li><strong><code>columnSettingKey</code></strong>：存在时，将 <strong><code>prop -&gt; visible</code></strong>（或完整可见状态快照）写入 <strong><code>localStorage</code></strong>；<strong>重置列设置</strong> 清除该 key 对应状态并恢复默认 <strong><code>_visible</code></strong>。</li><li><strong>列设置 UI</strong>：工具栏 <strong>列设置按钮</strong> 打开 <strong>Popover / Drawer</strong>（实现选型在 implementation plan 中确定，<strong>不影响</strong>对外契约）。</li></ul><hr><h2 id="_10-工具栏与内置操作" tabindex="-1">10. 工具栏与内置操作 <a class="header-anchor vp-link" href="#_10-工具栏与内置操作" aria-label="Permalink to &quot;10. 工具栏与内置操作&quot;">​</a></h2><ul><li><strong>左侧</strong>：<strong><code>toolbar-left</code></strong> slot；存在 <strong><code>deleteFunction</code></strong> 时 <strong>内置批量删除</strong>；存在 <strong><code>exportFunction</code></strong> 时 <strong>内置导出</strong>。</li><li><strong>右侧</strong>：<strong><code>toolbar-right</code></strong> slot；<strong>列设置</strong>、<strong>刷新</strong>。</li><li><strong><code>search-extra</code></strong>：搜索区额外扩展 slot。</li></ul><p><strong>删除</strong>：</p><ul><li><strong><code>beforeDelete(ids, rows)</code></strong>：返回 <strong><code>false</code></strong> 则 <strong>取消</strong>。</li><li>否则 <strong>内置 <code>ElMessageBox.confirm</code></strong>（文案可 prop 化，首版可用默认中文）。</li><li><strong><code>deleteFunction(ids)</code></strong>；<strong><code>checkDeleteSuccess(res)</code></strong> 可选，缺省时 <strong><code>!!res</code></strong> 或项目惯例（实现时与现有列表删除对齐）。</li><li>成功：<strong>提示</strong> + <strong><code>emit(&#39;delete-success&#39;, ids)</code></strong> + <strong><code>refreshData()</code></strong>。</li></ul><p><strong>导出（澄清 3B）</strong>：</p><ul><li><strong><code>exportFunction()</code></strong> 返回 <strong><code>Promise&lt;Blob | { data: Blob, headers }&gt;</code></strong>，与 <strong><code>C7ExcelDownload</code></strong> / <strong><code>downloadRequest(..., { returnBlobWithHeaders: true })</code></strong> 一致。</li><li><strong>参数</strong>：使用 <strong>发起导出时刻的 <code>searchParam</code> 深拷贝快照</strong>（与原始需求一致）。</li><li><strong>Loading</strong>：<strong><code>exportLoadingOptions === false</code></strong> 时不使用 <strong><code>ElLoading.service</code></strong>；否则导出 Promise 期间 <strong>全屏 Loading</strong>（与原始需求一致）。可与 <strong><code>C7ExcelDownload</code></strong> 的 <strong><code>v-model:downloading</code></strong> 组合使用，<strong>避免</strong>重复 loading（实现细节：二选一或统一由 <strong><code>C7ExcelDownload</code></strong> 管理按钮 loading、由 JsonTable 管全屏，在 plan 中写清）。</li><li>成功：<strong><code>emit(&#39;export-success&#39;)</code></strong>；失败走 <strong>下载组件 / 请求</strong> 既有错误提示路径。</li></ul><hr><h2 id="_11-事件与-expose-与原始需求对齐" tabindex="-1">11. 事件与 Expose（与原始需求对齐） <a class="header-anchor vp-link" href="#_11-事件与-expose-与原始需求对齐" aria-label="Permalink to &quot;11. 事件与 Expose（与原始需求对齐）&quot;">​</a></h2><p><strong>事件</strong>：<strong><code>before-fetch</code></strong>、<strong><code>after-fetch</code></strong>、<strong><code>selection-change</code></strong>、<strong><code>sort-change</code></strong>、<strong><code>delete-success</code></strong>、<strong><code>export-success</code></strong>、<strong><code>fetch-error</code></strong>（或统一命名，见 §6）。</p><p><strong>Expose</strong>：<strong><code>refreshData</code></strong>（当前页）、<strong><code>getDataList</code></strong>（回第一页并拉数）、<strong><code>selectedRows</code></strong>、<strong><code>searchParam</code></strong>、<strong><code>currentPage</code></strong>、<strong><code>currentPageSize</code></strong>、<strong><code>total</code></strong>、<strong><code>tableRef</code></strong>（<code>el-table</code> 实例）。</p><hr><h2 id="_12-测试建议" tabindex="-1">12. 测试建议 <a class="header-anchor vp-link" href="#_12-测试建议" aria-label="Permalink to &quot;12. 测试建议&quot;">​</a></h2><ul><li><strong>组件/逻辑</strong>：请求参数组装、<strong><code>rowsKey</code>/<code>totalKey</code></strong> 解析、列设置与 localStorage 合并、<strong><code>before-delete</code></strong> 取消路径。</li><li><strong>E2E（可选）</strong>：新增 Dev 路由页，<strong>mock <code>listFunction</code></strong>、导出 <strong>Blob</strong>、删除 <strong>mock</strong>，覆盖主路径。</li></ul><hr><h2 id="_13-自检摘要" tabindex="-1">13. 自检摘要 <a class="header-anchor vp-link" href="#_13-自检摘要" aria-label="Permalink to &quot;13. 自检摘要&quot;">​</a></h2><ul><li><strong>无 TBD</strong>：<strong><code>before-fetch</code> 返回 false</strong> 是否与项目 request 一致，已在 §6 要求实现前 <strong>代码核对后二选一写死</strong>。</li><li><strong>与列设计一致</strong>：多选/序号在 <strong>JsonTable</strong>；列渲染在 <strong><code>C7JsonTableColumn</code></strong>；<strong><code>#table-columns</code></strong> 覆盖列子树。</li><li><strong>范围</strong>：搜索为 <strong>JsonForm 子集</strong>；树表仅 <strong>透传</strong>；列持久化 <strong>仅 localStorage</strong>。</li></ul>',49)])])}const p=e(n,[["render",g]]);export{h as __pageData,p as default};
